 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    # Continue colored diagonal rays, using repeated same-color diagonal neighbors.
    for color in set(v for row in grid for v in row):
        if color in (4, 7):
            continue
        pts = [(r,c) for r in range(h) for c in range(w) if grid[r][c] == color]
        for dr,dc in ((1,1),(1,-1)):
            for r,c in pts:
                # only start from endpoint of existing diagonal run
                pr,pc=r-dr,c-dc
                if 0 <= pr < h and 0 <= pc < w and grid[pr][pc] == color:
                    continue
                nr,nc=r+dr,c+dc
                if not (0 <= nr < h and 0 <= nc < w and grid[nr][nc] == color):
                    continue
                er,ec=nr,nc
                while 0 <= er+dr < h and 0 <= ec+dc < w and grid[er+dr][ec+dc] == color:
                    er,ec=er+dr,ec+dc
                rr,cc=er+dr,ec+dc
                while 0 <= rr < h and 0 <= cc < w:
                    if out[rr][cc] not in (grid[0][0], color):
                        break
                    out[rr][cc]=color
                    rr+=dr; cc+=dc
    return out
